class SingleInstanceGuard:
    """Prevent two Shower Programmer copies from running on one Windows user session."""

    MUTEX_NAME = r"Local\BarefootShowersProgrammerDesktopApp"

    def __init__(self) -> None:
        self._handle: int | None = None
        self._fallback_path: Path | None = None

    def acquire(self) -> bool:
        if os.name == "nt":
            kernel32 = ctypes.windll.kernel32
            kernel32.CreateMutexW.argtypes = [ctypes.c_void_p, ctypes.c_bool, ctypes.c_wchar_p]
            kernel32.CreateMutexW.restype = ctypes.c_void_p
            handle = kernel32.CreateMutexW(None, False, self.MUTEX_NAME)
            if not handle:
                raise ctypes.WinError()
            if kernel32.GetLastError() == 183:  # ERROR_ALREADY_EXISTS
                kernel32.CloseHandle(handle)
                return False
            self._handle = int(handle)
            return True

        # Development fallback for non-Windows systems. The production EXE uses the mutex above.
        lock_root = Path(tempfile.gettempdir()) / "Shower Programmer"
        lock_root.mkdir(parents=True, exist_ok=True)
        path = lock_root / "shower_programmer.instance.lock"
        try:
            descriptor = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        except FileExistsError:
            try:
                pid_text = path.read_text(encoding="utf-8").strip()
                pid = int(pid_text)
                os.kill(pid, 0)
                return False
            except (ValueError, ProcessLookupError, PermissionError, OSError):
                try:
                    path.unlink()
                except OSError:
                    return False
                descriptor = os.open(path, os.O_CREAT | os.O_EXCL | os.O_WRONLY)
        with os.fdopen(descriptor, "w", encoding="utf-8") as handle:
            handle.write(str(os.getpid()))
        self._fallback_path = path
        return True

    def release(self) -> None:
        if self._handle is not None and os.name == "nt":
            try:
                ctypes.windll.kernel32.CloseHandle(ctypes.c_void_p(self._handle))
            except Exception:
                pass
            self._handle = None
        if self._fallback_path is not None:
            try:
                self._fallback_path.unlink()
            except OSError:
                pass
            self._fallback_path = None


def friendly_error_message(action: str, error: object) -> str:
    """Turn common file and integration failures into instructions a shop user can follow."""
    detail = str(error).strip() or error.__class__.__name__
    lower = detail.casefold()
    is_update = "update" in action.casefold()

    if is_update:
        if "404" in lower or "not found" in lower and "github" in lower:
            message = (
                "The GitHub update package could not be found. Rebuild and publish "
                "release/Shower-Programmer-Windows.zip, or check the repository configuration."
            )
        elif (
            "filename or extension is too long" in lower
            or "path too long" in lower
            or "winerror 206" in lower
            or "errno 36" in lower
        ):
            message = "The update package contains a Windows path that is too long to extract safely."
        elif isinstance(error, PermissionError) or "access is denied" in lower or "permission" in lower:
            message = "The updater could not write to the staging or installation folder."
        elif "being used by another process" in lower or "sharing violation" in lower or "locked" in lower:
            message = (
                "Close any open Shower Programmer, PDF, DXF, NCEditor, AutoCAD, or File Explorer Preview "
                "windows and try again."
            )
        elif isinstance(error, FileNotFoundError) or "no such file or directory" in lower:
            message = "The downloaded update package was incomplete or could not be extracted safely."
        else:
            message = f"{action} failed.\n\n{detail}"
        return message + "\n\nYour current Shower Programmer installation was not changed."

    if isinstance(error, AttributeError):
        return (
            f"{action} could not start because the installed program files do not match each other.\n\n"
            "Close Shower Programmer, replace Backend\\shower_programmer_gui.py with the latest supplied file, "
            "and rebuild using the included Rebuild Shower Programmer EXE.bat.\n\n"
            f"Technical detail: {detail}"
        )
    if isinstance(error, PermissionError) or "being used by another process" in lower:
        return (
            f"{action} could not access a file because Windows says it is in use.\n\n"
            "Close any second Shower Programmer window and close the affected PDF, DXF, or process list in other programs, "
            "then try again.\n\n"
            f"Technical detail: {detail}"
        )
    if isinstance(error, FileExistsError):
        return (
            f"{action} encountered a temporary-file conflict. This usually means two copies were working in the same "
            "local folders. Close the other copy and try again.\n\n"
            f"Technical detail: {detail}"
        )
    return f"{action} failed.\n\n{detail}"


class ModernProgressBar:
    """Small CustomTkinter progress wrapper with the ttk Progressbar methods this app uses."""

    def __init__(self, parent: Any, app: "ShowerProgrammerApp", height: int = 12) -> None:
        self.app = app
        self.maximum = 100.0
        self.value = 0.0
        self.mode = "determinate"
        self.widget = ctk.CTkProgressBar(
            parent,
            mode="determinate",
            height=height,
            corner_radius=max(6, height // 2),
            border_width=0,
            fg_color=app.PROGRESS_TRACK,
            progress_color=app.PROGRESS_FILL,
        )
        self.widget.set(0.0)

    def configure(self, **kwargs: Any) -> None:
        if "maximum" in kwargs:
            try:
                self.maximum = max(float(kwargs.pop("maximum")), 1.0)
            except (TypeError, ValueError):
                self.maximum = 100.0
        if "mode" in kwargs:
            self.mode = str(kwargs.pop("mode") or "determinate")
            try:
                self.widget.configure(mode=self.mode)
            except (tk.TclError, RuntimeError):
                pass
        if "value" in kwargs:
            try:
                self.value = float(kwargs.pop("value"))
            except (TypeError, ValueError):
                self.value = 0.0
            self._sync_value()
        if "progress_color" not in kwargs:
            kwargs["progress_color"] = self.app.PROGRESS_FILL
        if "fg_color" not in kwargs:
            kwargs["fg_color"] = self.app.PROGRESS_TRACK
        try:
            self.widget.configure(**kwargs)
        except tk.TclError:
            pass

    config = configure

    def _sync_value(self) -> None:
        ratio = max(0.0, min(1.0, self.value / max(self.maximum, 1.0)))
        try:
            self.widget.set(ratio)
        except tk.TclError:
            pass

    def step(self, amount: float = 1.0) -> None:
        try:
            self.value += float(amount)
        except (TypeError, ValueError):
            self.value += 1.0
        self._sync_value()

    def start(self, *_args: Any) -> None:
        try:
            self.widget.configure(mode="indeterminate")
            self.widget.start()
        except tk.TclError:
            pass

    def stop(self) -> None:
        try:
            self.widget.stop()
            self.widget.configure(mode=self.mode)
        except tk.TclError:
            pass

    def grid(self, *args: Any, **kwargs: Any) -> Any:
        return self.widget.grid(*args, **kwargs)

    def pack(self, *args: Any, **kwargs: Any) -> Any:
        return self.widget.pack(*args, **kwargs)

    def place(self, *args: Any, **kwargs: Any) -> Any:
        return self.widget.place(*args, **kwargs)

    def destroy(self) -> None:
        self.widget.destroy()

    def __getattr__(self, name: str) -> Any:
        return getattr(self.widget, name)


