    def force_main_window_maximized(self) -> None:
        """Keep the main application maximized after theme/startup rebuilds."""
        def maximize() -> None:
            try:
                self.root.update_idletasks()
                self.maximize_window(self.root)
            except tk.TclError:
                pass

        maximize()
        for delay in (50, 200, 650):
            try:
                self.root.after(delay, maximize)
            except tk.TclError:
                pass

    @classmethod
    def preferred_runtime_root(cls) -> Path:
        root = programmer.project_root()
        try:
            root.mkdir(parents=True, exist_ok=True)
            with tempfile.NamedTemporaryFile("w", delete=True, dir=str(root), encoding="utf-8"):
                pass
            return root
        except Exception:
            appdata = os.environ.get("APPDATA")
            base = Path(appdata) if appdata else Path.home() / "AppData" / "Roaming"
            return base / "Shower Programmer"

    def ensure_internal_runtime_folders(self) -> Path:
        root = self.preferred_runtime_root()
        self.ensure_workflow_folders(
            root / "Input" / "Orders",
            root / "Input" / "Process List",
            root / "Output",
        )
        return root

    @staticmethod
    def ensure_workflow_folders(order_folder: Path, process_list_path: Path, output_dir: Path) -> list[Path]:
        process_list_is_file = process_list_path.is_file() or process_list_path.suffix.lower() in ShowerProgrammerApp.PROCESS_LIST_FILE_EXTENSIONS
        process_list_dir = process_list_path.parent if process_list_is_file else process_list_path
        folders = [
            order_folder,
            process_list_dir,
            output_dir,
            output_dir / "Runs",
            output_dir / "Updates",
        ]
        created: list[Path] = []
        for folder in folders:
            existed = folder.exists()
            if existed and not folder.is_dir():
                raise NotADirectoryError(f"Required workflow path is not a folder: {folder}")
            folder.mkdir(parents=True, exist_ok=True)
            if not existed:
                created.append(folder)
        return created

    @staticmethod
    def atomic_write_json(path: Path, data: object) -> None:
        path.parent.mkdir(parents=True, exist_ok=True)
        temporary = path.with_name(f".{path.name}.{uuid.uuid4().hex}.tmp")
        try:
            with temporary.open("w", encoding="utf-8") as handle:
                json.dump(data, handle, indent=2, sort_keys=True)
                handle.flush()
                os.fsync(handle.fileno())
            last_error: OSError | None = None
            for attempt in range(6):
                try:
                    os.replace(temporary, path)
                    return
                except PermissionError as exc:
                    last_error = exc
                    time.sleep(0.04 * (attempt + 1))
            if last_error is not None:
                raise last_error
        finally:
            try:
                temporary.unlink(missing_ok=True)
            except OSError:
                pass

    def quarantine_root(self) -> Path:
        root = Path(getattr(self, "runtime_root", self.preferred_runtime_root())) / self.QUARANTINE_FOLDER_NAME
        root.mkdir(parents=True, exist_ok=True)
        return root

    def diagnostics_directory(self) -> Path:
        path = Path(getattr(self, "runtime_root", self.preferred_runtime_root())) / self.DIAGNOSTICS_FOLDER_NAME
        path.mkdir(parents=True, exist_ok=True)
        return path

    @classmethod
    def quarantine_paths(
        cls,
        quarantine_root: Path,
        paths: Iterable[Path],
        allowed_roots: Iterable[Path],
        aw_orders: Iterable[str],
        *,
        bundle_id: str | None = None,
        now: datetime | None = None,
        progress_callback: Callable[[int, int, Path], None] | None = None,
    ) -> tuple[list[Path], list[str], str | None]:
        """Move local workflow files into a seven-day, manifest-backed recovery bundle."""
        stamp = now or datetime.now()
        roots = [root.resolve() for root in allowed_roots]
        if not roots:
            raise ValueError("At least one allowed local folder is required.")
        quarantine_root = quarantine_root.resolve()
        quarantine_root.mkdir(parents=True, exist_ok=True)
        bundle_id = bundle_id or f"{stamp.strftime('%Y%m%d-%H%M%S')}-{uuid.uuid4().hex[:8]}"
        bundle_dir = (quarantine_root / bundle_id).resolve()
        try:
            bundle_dir.relative_to(quarantine_root)
        except ValueError as exc:
            raise ValueError("Invalid recovery bundle identifier.") from exc
        bundle_dir.mkdir(parents=True, exist_ok=True)
        manifest_path = bundle_dir / "manifest.json"
        if manifest_path.exists():
            try:
                manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
            except (OSError, ValueError) as exc:
                raise RuntimeError(f"Could not read recovery manifest {bundle_id}: {exc}") from exc
            existing_roots = [Path(value).resolve() for value in manifest.get("allowed_roots", [])]
            for root in roots:
                if root not in existing_roots:
                    existing_roots.append(root)
            roots = existing_roots
            manifest["allowed_roots"] = [str(root) for root in roots]
        else:
            manifest = {
                "schema": 1,
                "bundle_id": bundle_id,
                "created_at": stamp.isoformat(timespec="seconds"),
                "expires_at": (stamp + timedelta(days=cls.QUARANTINE_RETENTION_DAYS)).isoformat(timespec="seconds"),
                "orders": [],
                "allowed_roots": [str(root) for root in roots],
                "files": [],
            }
        manifest["orders"] = sorted(
            set(str(value) for value in manifest.get("orders", []))
            | {str(value) for value in aw_orders if str(value)}
        )
        entries = manifest.setdefault("files", [])
        if not isinstance(entries, list):
            raise RuntimeError("The recovery manifest file list is invalid.")
        moved: list[Path] = []
        warnings: list[str] = []
        seen: set[str] = set()
        source_paths = [Path(source_value) for source_value in paths]
        progress_total = len(source_paths)
        progress_done = 0

        def report_progress(source: Path) -> None:
            nonlocal progress_done
            progress_done += 1
            if progress_callback is not None:
                progress_callback(progress_done, max(progress_total, 1), source)

        for source in source_paths:
            try:
                resolved = source.resolve()
                root_index = next(
                    index for index, root in enumerate(roots)
                    if resolved == root or resolved.is_relative_to(root)
                )
            except (OSError, StopIteration):
                warnings.append(f"Skipped file outside approved local folders: {source.name}")
                report_progress(source)
                continue
            key = str(resolved).casefold()
            if key in seen or not resolved.is_file():
                report_progress(source)
                continue
            seen.add(key)
            relative = resolved.relative_to(roots[root_index])
            target = bundle_dir / "files" / f"root-{root_index + 1}" / relative
            target = cls.unique_target_path(target)
            try:
                size = resolved.stat().st_size
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.move(str(resolved), str(target))
                entries.append(
                    {
                        "original_path": str(resolved),
                        "quarantined_path": str(target.relative_to(bundle_dir)),
                        "size": size,
                        "restored": False,
                    }
                )
                moved.append(resolved)
                cls.atomic_write_json(manifest_path, manifest)
            except OSError as exc:
                warnings.append(f"Could not move {source.name} to recovery: {exc}")
            report_progress(source)
        if not entries:
            shutil.rmtree(bundle_dir, ignore_errors=True)
            return moved, warnings, None
        cls.atomic_write_json(manifest_path, manifest)
        return moved, warnings, bundle_id

    @classmethod
    def quarantine_bundles(cls, quarantine_root: Path) -> list[dict[str, object]]:
        bundles: list[dict[str, object]] = []
        if not quarantine_root.is_dir():
            return bundles
        root = quarantine_root.resolve()
        for manifest_path in root.glob("*/manifest.json"):
            try:
                if not manifest_path.resolve().is_relative_to(root):
                    continue
                data = json.loads(manifest_path.read_text(encoding="utf-8"))
                if not isinstance(data, dict) or not isinstance(data.get("files"), list):
                    continue
                data["_manifest_path"] = str(manifest_path)
                bundles.append(data)
            except (OSError, ValueError, TypeError):
                continue
        return sorted(bundles, key=lambda item: str(item.get("created_at", "")), reverse=True)

    @classmethod
    def restore_quarantine_bundle(cls, quarantine_root: Path, bundle_id: str) -> tuple[list[Path], list[str]]:
        root = quarantine_root.resolve()
        bundle_dir = (root / bundle_id).resolve()
        try:
            bundle_dir.relative_to(root)
        except ValueError as exc:
            raise ValueError("Invalid recovery bundle.") from exc
        manifest_path = bundle_dir / "manifest.json"
        data = json.loads(manifest_path.read_text(encoding="utf-8"))
        allowed_roots = [Path(value).resolve() for value in data.get("allowed_roots", [])]
        restored: list[Path] = []
        warnings: list[str] = []
        for entry in data.get("files", []):
            if not isinstance(entry, dict) or bool(entry.get("restored")):
                continue
            source = (bundle_dir / str(entry.get("quarantined_path", ""))).resolve()
            target = Path(str(entry.get("original_path", ""))).resolve()
            if not source.is_relative_to(bundle_dir) or not any(target.is_relative_to(base) for base in allowed_roots):
                warnings.append("Skipped an unsafe recovery manifest entry.")
                continue
            if not source.is_file():
                warnings.append(f"Recovery copy is missing: {source.name}")
                continue
            if target.exists():
                target = cls.unique_target_path(target.with_name(f"{target.stem} (restored){target.suffix}"))
            try:
                target.parent.mkdir(parents=True, exist_ok=True)
                shutil.move(str(source), str(target))
                entry["restored"] = True
                entry["restored_path"] = str(target)
                restored.append(target)
            except OSError as exc:
                warnings.append(f"Could not restore {source.name}: {exc}")
        cls.atomic_write_json(manifest_path, data)
        if all(bool(entry.get("restored")) for entry in data.get("files", []) if isinstance(entry, dict)):
            shutil.rmtree(bundle_dir, ignore_errors=True)
        return restored, warnings

    @classmethod
    def delete_quarantine_bundle(cls, quarantine_root: Path, bundle_id: str) -> None:
        root = quarantine_root.resolve()
        bundle_dir = (root / bundle_id).resolve()
        if bundle_dir == root or not bundle_dir.is_relative_to(root):
            raise ValueError("Invalid recovery bundle.")
        shutil.rmtree(bundle_dir)

    def cleanup_expired_quarantine(self) -> None:
        now = datetime.now()
        for bundle in self.quarantine_bundles(self.quarantine_root()):
            try:
                expires = datetime.fromisoformat(str(bundle.get("expires_at", "")))
                if expires <= now:
                    self.delete_quarantine_bundle(self.quarantine_root(), str(bundle.get("bundle_id", "")))
            except (OSError, ValueError, TypeError):
                continue

    @staticmethod
    def probe_network_path(path: Path) -> dict[str, object]:
        started = time.perf_counter()
        try:
            if not path.is_dir():
                raise FileNotFoundError(str(path))
            with os.scandir(path) as entries:
                next(entries, None)
            return {"path": str(path), "reachable": True, "elapsed_ms": round((time.perf_counter() - started) * 1000)}
        except Exception as exc:
            return {
                "path": str(path),
                "reachable": False,
                "elapsed_ms": round((time.perf_counter() - started) * 1000),
                "error": str(exc),
            }

    def network_health_targets(self) -> dict[str, Path]:
        return {
            "Import folder": Path(self.import_source_var.get()),
            "Shop sketches": Path(self.SHOP_SKETCHES_DIR),
            "Shop programs": Path(self.SHOP_PROGRAMS_DIR),
        }

    def check_network_health_async(self) -> None:
        if self.network_health_running:
            return
        self.network_health_running = True
        self.network_health_var.set("Network: Checking")
        targets = self.network_health_targets()

        def worker() -> None:
            results: dict[str, dict[str, object]] = {}
            result_queue: queue.Queue[tuple[str, dict[str, object]]] = queue.Queue()
            for name, path in targets.items():
                threading.Thread(
                    target=lambda label=name, candidate=path: result_queue.put((label, self.probe_network_path(candidate))),
                    daemon=True,
                ).start()
            deadline = time.monotonic() + self.NETWORK_HEALTH_TIMEOUT_SECONDS
            while len(results) < len(targets) and time.monotonic() < deadline:
                try:
                    name, result = result_queue.get(timeout=max(0.05, deadline - time.monotonic()))
                    results[name] = result
                except queue.Empty:
                    break
            for name, path in targets.items():
                results.setdefault(name, {"path": str(path), "reachable": False, "error": "Timed out"})
            try:
                self.root.after(0, lambda: self.apply_network_health_results(results))
            except (tk.TclError, RuntimeError):
                pass

        threading.Thread(target=worker, daemon=True).start()

    def apply_network_health_results(self, results: dict[str, dict[str, object]]) -> None:
        self.network_health_running = False
        self.network_health_details = results
        online = sum(bool(result.get("reachable")) for result in results.values())
        total = len(results)
        if online == total:
            label, color = "Network: Online", self.SUCCESS
        elif online:
            label, color = f"Network: {online}/{total} Online", self.WARNING
        else:
            label, color = "Network: Offline", self.DANGER
        self.network_health_var.set(label)
        button = getattr(self, "network_health_button", None)
        if button is not None:
            try:
                button.configure(text=label, border_color=color, text_color=color)
            except tk.TclError:
                pass
        if self.network_health_after_id is not None:
            try:
                self.root.after_cancel(self.network_health_after_id)
            except tk.TclError:
                pass
        self.network_health_after_id = self.root.after(self.NETWORK_HEALTH_REFRESH_MS, self.check_network_health_async)

    @classmethod
    def export_configuration_backup(cls, target: Path, config_path: Path, ui_settings_path: Path) -> Path:
        config = json.loads(config_path.read_text(encoding="utf-8"))
        if not isinstance(config, dict):
            raise ValueError("The programmer configuration is not a JSON object.")
        ui_settings: dict[str, object] = {}
        if ui_settings_path.is_file():
            loaded = json.loads(ui_settings_path.read_text(encoding="utf-8"))
            if not isinstance(loaded, dict):
                raise ValueError("The UI settings file is not a JSON object.")
            ui_settings = loaded
        target = target.with_suffix(".zip")
        target.parent.mkdir(parents=True, exist_ok=True)
        temporary = target.with_name(f".{target.name}.{uuid.uuid4().hex}.tmp")
        manifest = {
            "schema": 1,
            "created_at": datetime.now().isoformat(timespec="seconds"),
            "application_version": cls.APP_VERSION,
            "files": ["shower_programmer_config.json", cls.UI_SETTINGS_FILE_NAME],
        }
        with zipfile.ZipFile(temporary, "w", compression=zipfile.ZIP_DEFLATED) as archive:
            archive.writestr("backup_manifest.json", json.dumps(manifest, indent=2, sort_keys=True))
            archive.writestr("shower_programmer_config.json", json.dumps(config, indent=2, sort_keys=True))
            archive.writestr(cls.UI_SETTINGS_FILE_NAME, json.dumps(ui_settings, indent=2, sort_keys=True))
        os.replace(temporary, target)
        return target

    @classmethod
    def import_configuration_backup(
        cls,
        archive_path: Path,
        config_path: Path,
        ui_settings_path: Path,
        auto_backup_dir: Path,
    ) -> dict[str, object]:
        allowed = {"backup_manifest.json", "shower_programmer_config.json", cls.UI_SETTINGS_FILE_NAME}
        with zipfile.ZipFile(archive_path, "r") as archive:
            names = {member.filename.replace("\\", "/") for member in archive.infolist() if not member.is_dir()}
            if not names or not names.issubset(allowed) or "shower_programmer_config.json" not in names:
                raise ValueError("This is not a valid Shower Programmer configuration backup.")
            config = json.loads(archive.read("shower_programmer_config.json").decode("utf-8"))
            ui_settings = (
                json.loads(archive.read(cls.UI_SETTINGS_FILE_NAME).decode("utf-8"))
                if cls.UI_SETTINGS_FILE_NAME in names
                else {}
            )
        if not isinstance(config, dict) or not isinstance(ui_settings, dict):
            raise ValueError("The configuration backup contains invalid JSON data.")
        auto_backup_dir.mkdir(parents=True, exist_ok=True)
        if config_path.is_file():
            backup_target = auto_backup_dir / f"before-import-{datetime.now().strftime('%Y%m%d-%H%M%S')}.zip"
            cls.export_configuration_backup(backup_target, config_path, ui_settings_path)
        cls.atomic_write_json(config_path, config)
        cls.atomic_write_json(ui_settings_path, ui_settings)
        return {"config": config, "ui_settings": ui_settings}

    def internal_orders_dir(self) -> Path:
        return Path(getattr(self, "runtime_root", self.preferred_runtime_root())) / "Input" / "Orders"

    def internal_process_list_dir(self) -> Path:
        return Path(getattr(self, "runtime_root", self.preferred_runtime_root())) / "Input" / "Process List"

    def internal_output_dir(self) -> Path:
        return Path(getattr(self, "runtime_root", self.preferred_runtime_root())) / "Output"

    @staticmethod
    def set_window_icon(window: Any) -> None:
        png_path = ShowerProgrammerApp.APP_ICON_PNG_PATH
        if png_path.exists():
            try:
                photo = tk.PhotoImage(file=str(png_path))
                window.iconphoto(True, photo)
                window._shower_programmer_icon = photo
            except tk.TclError:
                pass
        icon_path = ShowerProgrammerApp.APP_ICON_PATH
        if not icon_path.exists():
            return
        try:
            window.iconbitmap(str(icon_path))
        except tk.TclError:
            pass

    @staticmethod
    def maximize_window(window: Any) -> None:
        """Use a real OS maximize state instead of borderless fullscreen.

        Fullscreen hides normal Windows caption controls and can cover the
        taskbar, so it is intentionally not used as a maximize fallback.
        """
        try:
            window.state("zoomed")
            return
        except tk.TclError:
            pass
        if os.name == "nt":
            try:
                window.update_idletasks()
                ctypes.windll.user32.ShowWindow(int(window.winfo_id()), 3)  # SW_MAXIMIZE
                return
            except Exception:
                pass
        try:
            window.attributes("-zoomed", True)
        except tk.TclError:
            pass

    @staticmethod
    def toggle_window_maximize(window: Any) -> None:
        try:
            current_state = str(window.state()).lower()
            window.state("normal" if current_state == "zoomed" else "zoomed")
            return
        except tk.TclError:
            pass
        if os.name == "nt":
            try:
                window.update_idletasks()
                hwnd = int(window.winfo_id())
                is_zoomed = bool(ctypes.windll.user32.IsZoomed(hwnd))
                ctypes.windll.user32.ShowWindow(hwnd, 9 if is_zoomed else 3)  # SW_RESTORE / SW_MAXIMIZE
                return
            except Exception:
                pass
        try:
            window.attributes("-zoomed", not bool(window.attributes("-zoomed")))
        except tk.TclError:
            pass

    def position_child_window(self, window: tk.Toplevel, width: int, height: int) -> None:
        try:
            self.root.update_idletasks()
            root_x = self.root.winfo_rootx()
            root_y = self.root.winfo_rooty()
            root_w = max(self.root.winfo_width(), 1)
            root_h = max(self.root.winfo_height(), 1)
            x = root_x + max(24, min(80, root_w // 12))
            y = root_y + max(24, min(80, root_h // 12))
            window.geometry(f"{width}x{height}+{x}+{y}")
        except tk.TclError:
            window.geometry(f"{width}x{height}")

    def center_child_window(self, window: tk.Toplevel, width: int, height: int) -> None:
        """Center a child on the same display area as the main application."""
        try:
            self.root.update_idletasks()
            root_x = self.root.winfo_rootx()
            root_y = self.root.winfo_rooty()
            root_w = max(self.root.winfo_width(), 1)
            root_h = max(self.root.winfo_height(), 1)
            width = min(width, max(900, root_w - 64))
            height = min(height, max(640, root_h - 64))
            x = root_x + max(0, (root_w - width) // 2)
            y = root_y + max(0, (root_h - height) // 2)
            window.geometry(f"{width}x{height}+{x}+{y}")
        except tk.TclError:
            window.geometry(f"{width}x{height}")

    def bring_window_to_front(self, window: tk.Toplevel, make_transient: bool = True) -> None:
        def apply_focus() -> None:
            try:
                window.deiconify()
            except tk.TclError:
                pass
            if make_transient:
                try:
                    window.transient(self.root)
                except tk.TclError:
                    pass
            try:
                window.lift()
                window.focus_force()
            except tk.TclError:
                pass
            try:
                window.attributes("-topmost", True)
                window.after(350, lambda: window.attributes("-topmost", False))
            except tk.TclError:
                pass

        try:
            window.after(75, apply_focus)
        except tk.TclError:
            pass


    def managed_page_window(self, page_key: str) -> tk.Toplevel | None:
        """Return a live registered page window, clearing stale references automatically."""
        windows = getattr(self, "managed_page_windows", None)
        if not isinstance(windows, dict):
            self.managed_page_windows = {}
            return None
        window = windows.get(page_key)
        if window is None:
            return None
        try:
            if bool(window.winfo_exists()):
                return window
        except (AttributeError, tk.TclError):
            pass
        windows.pop(page_key, None)
        return None

    def register_page_window(self, page_key: str, window: tk.Toplevel) -> None:
        """Register one major child page and remove it from the registry when destroyed."""
        if not isinstance(getattr(self, "managed_page_windows", None), dict):
            self.managed_page_windows = {}
        self.managed_page_windows[page_key] = window

        def unregister(event: tk.Event | None = None) -> None:
            if event is not None and getattr(event, "widget", None) is not window:
                return
            windows = getattr(self, "managed_page_windows", None)
            if isinstance(windows, dict) and windows.get(page_key) is window:
                windows.pop(page_key, None)

        try:
            window.bind("<Destroy>", unregister, add="+")
        except (AttributeError, tk.TclError):
            pass

    def bring_page_window_to_front(self, window: tk.Toplevel) -> None:
        """Restore and reliably activate an existing child page above the main window."""

        def activate() -> None:
            try:
                if not bool(window.winfo_exists()):
                    return
            except (AttributeError, tk.TclError):
                return
            try:
                if str(window.state()).casefold() == "iconic":
                    window.deiconify()
                else:
                    window.deiconify()
            except (AttributeError, tk.TclError):
                pass
            try:
                window.lift()
            except (AttributeError, tk.TclError):
                pass
            try:
                window.attributes("-topmost", True)
            except (AttributeError, tk.TclError):
                pass
            try:
                window.update_idletasks()
            except (AttributeError, tk.TclError):
                pass
            try:
                window.focus_set()
            except (AttributeError, tk.TclError):
                pass
            try:
                window.focus_force()
            except (AttributeError, tk.TclError):
                pass

        def release_topmost() -> None:
            try:
                if bool(window.winfo_exists()):
                    window.attributes("-topmost", False)
                    window.lift()
                    window.focus_force()
            except (AttributeError, tk.TclError):
                pass

        activate()
        try:
            window.after(60, activate)
            window.after(450, release_topmost)
        except (AttributeError, tk.TclError):
            pass

    def focus_existing_page_window(
        self,
        page_key: str,
        page_name: str,
        *,
        show_notice: bool = True,
    ) -> bool:
        """Focus an existing major page instead of opening a duplicate instance."""
        window = self.managed_page_window(page_key)
        if window is None:
            return False
        self.bring_page_window_to_front(window)
        message = f"{page_name} is already open. The existing window was brought to the front."
        status_var = getattr(self, "status_var", None)
        try:
            if status_var is not None:
                status_var.set(message)
        except (AttributeError, tk.TclError):
            pass
        try:
            window.bell()
        except (AttributeError, tk.TclError):
            pass
        if show_notice:
            try:
                messagebox.showinfo("Page already open", message, parent=window)
            except (AttributeError, tk.TclError):
                messagebox.showinfo("Page already open", message)
            # The modal notice can briefly take focus. Raise the existing page
            # again after it closes so it remains the active window.
            self.bring_page_window_to_front(window)
        return True

    def block_recent_external_page_launch(
        self,
        page_key: str,
        page_name: str,
        *,
        cooldown_seconds: float = 3.0,
        show_notice: bool = True,
    ) -> bool:
        """Block accidental double-clicks for reviews opened by PDF viewers or web browsers."""
        launches = getattr(self, "recent_external_page_launches", None)
        if not isinstance(launches, dict):
            launches = {}
            self.recent_external_page_launches = launches
        now = time.monotonic()
        last = float(launches.get(page_key, 0.0) or 0.0)
        if last > 0.0 and now - last < max(0.25, float(cooldown_seconds)):
            message = f"{page_name} is already opening. Please use the page that was just opened."
            status_var = getattr(self, "status_var", None)
            try:
                if status_var is not None:
                    status_var.set(message)
            except (AttributeError, tk.TclError):
                pass
            if show_notice:
                messagebox.showinfo("Page already opening", message, parent=getattr(self, "root", None))
            return True
        launches[page_key] = now
        return False

    @staticmethod
    def dispatch_context_menu_action(
        parent: tk.Widget,
        command: object,
        hide_popup: Callable[[], None],
        destroy_popup: Callable[[], None],
        *,
        delay_ms: int = 20,
        on_error: Callable[[BaseException], None] | None = None,
    ) -> None:
        """Run the selected action immediately, then retire the hidden popup later.

        Destructive order actions must not depend on the Treeview still having the
        same selection after the context-menu Toplevel has been withdrawn.  The
        command therefore runs synchronously after the popup is hidden, while the
        potentially fragile CustomTkinter destruction is deferred until afterward.
        """
        try:
            hide_popup()
        except Exception:
            pass

        try:
            if callable(command):
                command()
        except Exception as exc:
            if on_error is not None:
                on_error(exc)
            else:
                raise

        def finish_popup_teardown() -> None:
            try:
                destroy_popup()
            except Exception:
                pass

        try:
            parent.after(delay_ms, finish_popup_teardown)
        except Exception:
            finish_popup_teardown()

    def close_active_themed_context_menu(self) -> None:
        binding = self.active_themed_context_binding
        if binding is not None:
            widget, sequence, funcid = binding
            try:
                widget.unbind(sequence, funcid)
            except tk.TclError:
                pass
            self.active_themed_context_binding = None

        popup = self.active_themed_context_popup
        self.active_themed_context_popup = None
        if popup is not None:
            try:
                if popup.winfo_exists():
                    popup.destroy()
            except tk.TclError:
                pass

    def show_themed_context_menu(
        self,
        parent: tk.Widget,
        x_root: int,
        y_root: int,
        title: str,
        subtitle: str,
        actions: list[dict[str, object]],
    ) -> None:
        self.close_active_themed_context_menu()
        if ctk is None:
            menu = tk.Menu(parent, tearoff=False)
            for action in actions:
                if action.get("separator"):
                    menu.add_separator()
                    continue
                command = action.get("command")
                menu.add_command(label=str(action.get("text", "")), command=command if callable(command) else None)
            try:
                menu.tk_popup(x_root, y_root)
            finally:
                menu.grab_release()
            return

        popup = ctk.CTkToplevel(parent)
        self.active_themed_context_popup = popup
        popup.withdraw()
        popup.overrideredirect(True)
        popup.configure(fg_color=self.CARD_BG)
        try:
            popup.transient(parent.winfo_toplevel())
        except tk.TclError:
            pass
        try:
            popup.attributes("-topmost", True)
        except tk.TclError:
            pass

        shell = ctk.CTkFrame(
            popup,
            fg_color=self.CARD_BG,
            corner_radius=12,
            border_width=1,
            border_color=self.BORDER,
        )
        shell.pack(fill=tk.BOTH, expand=True)

        def retire_popup(*, destroy: bool) -> None:
            """Hide the menu immediately and never let popup teardown block its action."""
            if self.active_themed_context_popup is popup:
                self.active_themed_context_popup = None
            binding = self.active_themed_context_binding
            if binding is not None:
                widget, sequence, funcid = binding
                try:
                    widget.unbind(sequence, funcid)
                except Exception:
                    pass
                if self.active_themed_context_binding == binding:
                    self.active_themed_context_binding = None
            try:
                popup.withdraw()
            except Exception:
                pass
            if not destroy:
                return
            try:
                if popup.winfo_exists():
                    popup.destroy()
            except Exception:
                # CustomTkinter descendant cleanup can occasionally raise after the
                # visible menu is already gone. The command must still be allowed to
                # run, so teardown failures are intentionally non-fatal here.
                pass

        header = ctk.CTkFrame(shell, fg_color=self.SOFT_CARD_BG, corner_radius=10)
        header.pack(fill=tk.X, padx=8, pady=(8, 6))
        header.grid_columnconfigure(0, weight=1)
        ctk.CTkLabel(
            header,
            text=title,
            font=("Segoe UI", 13, "bold"),
            text_color=self.TEXT,
            anchor="w",
        ).grid(row=0, column=0, sticky="ew", padx=(12, 8), pady=(8, 0))
        ctk.CTkLabel(
            header,
            text=subtitle,
            font=("Segoe UI", 10),
            text_color=self.MUTED,
            anchor="w",
        ).grid(row=1, column=0, sticky="ew", padx=(12, 8), pady=(0, 8))
        ctk.CTkButton(
            header,
            text="",
            command=lambda: retire_popup(destroy=True),
            width=28,
            height=28,
            corner_radius=8,
            fg_color="transparent",
            hover_color=self.ACCENT_LIGHT,
            text_color=self.MUTED,
            **self.ctk_button_icon("close", 13, self.MUTED, "left"),
        ).grid(row=0, column=1, rowspan=2, sticky="ne", padx=(0, 8), pady=8)

        body = ctk.CTkFrame(shell, fg_color="transparent")
        body.pack(fill=tk.BOTH, expand=True, padx=8, pady=(0, 8))

        def run_action(command: object, keep_open: bool = False) -> None:
            if keep_open:
                if callable(command):
                    command()
                try:
                    popup.lift()
                    popup.focus_force()
                except tk.TclError:
                    pass
                return

            # Hide and unregister the popup before dispatching the command, but do
            # not destroy it first. A CustomTkinter destroy exception here used to
            # prevent destructive order actions from ever reaching their handlers.
            def report_context_action_error(exc: BaseException) -> None:
                self.status_var.set(f"Context action failed: {exc}")
                self.show_structured_error(exc, title="Order action failed")

            self.dispatch_context_menu_action(
                parent,
                command,
                lambda: retire_popup(destroy=False),
                lambda: retire_popup(destroy=True),
                on_error=report_context_action_error,
            )

        for action in actions:
            if action.get("separator"):
                ctk.CTkFrame(body, fg_color=self.DIVIDER, height=1, corner_radius=0).pack(fill=tk.X, padx=6, pady=6)
                continue
            destructive = bool(action.get("destructive"))
            icon_color = self.DANGER if destructive else self.ACCENT_DARK
            text_color = self.DANGER if destructive else self.TEXT
            hover_color = "#fee4e2" if destructive and not self.dark_mode_var.get() else ("#3b1f24" if destructive else self.ACCENT_LIGHT)
            ctk.CTkButton(
                body,
                text=str(action.get("text", "")),
                command=lambda command=action.get("command"), keep_open=bool(action.get("keep_open")): run_action(command, keep_open),
                height=36,
                corner_radius=8,
                fg_color="transparent",
                hover_color=hover_color,
                text_color=text_color,
                font=("Segoe UI", 11, "bold"),
                anchor="w",
                **self.ctk_button_icon(str(action.get("icon", "info")), 16, icon_color, "left"),
            ).pack(fill=tk.X, pady=1)

        def cleanup_menu_state(_event: tk.Event | None = None) -> None:
            if self.active_themed_context_popup is popup:
                self.active_themed_context_popup = None
            binding = self.active_themed_context_binding
            if binding is not None:
                widget, sequence, funcid = binding
                try:
                    widget.unbind(sequence, funcid)
                except tk.TclError:
                    pass
                if self.active_themed_context_binding == binding:
                    self.active_themed_context_binding = None

        popup.bind("<Destroy>", cleanup_menu_state, add="+")

        popup.update_idletasks()
        try:
            screen_x = popup.winfo_vrootx()
            screen_y = popup.winfo_vrooty()
            screen_w = popup.winfo_vrootwidth()
            screen_h = popup.winfo_vrootheight()
        except tk.TclError:
            screen_x = 0
            screen_y = 0
            screen_w = popup.winfo_screenwidth()
            screen_h = popup.winfo_screenheight()
        width = popup.winfo_reqwidth()
        height = popup.winfo_reqheight()
        x_min = screen_x + 8
        y_min = screen_y + 8
        x_max = screen_x + screen_w - width - 12
        y_max = screen_y + screen_h - height - 48
        x = max(x_min, min(int(x_root), x_max))
        y = max(y_min, min(int(y_root), y_max))
        popup.geometry(f"{width}x{height}+{x}+{y}")
        popup.deiconify()
        try:
            popup.focus_force()
        except tk.TclError:
            pass

        def close_menu(_event: tk.Event | None = None) -> str:
            retire_popup(destroy=True)
            return "break"

        # Do not close this popup on FocusOut. On initial review-window open,
        # Windows/Tk can fire FocusOut immediately after an overrideredirect
        # popup is shown. Instead, install a delayed outside-click handler.
        # The delay keeps the original right-click that opened the menu from
        # immediately closing it again, while still letting a normal click away
        # close the menu and letting a second right-click replace it.
        popup.bind("<Escape>", close_menu)

        def install_outside_click_close() -> None:
            try:
                owner = parent.winfo_toplevel()
            except tk.TclError:
                return
            if self.active_themed_context_popup is not popup:
                return

            def close_if_clicked_outside(event: tk.Event) -> None:
                if self.active_themed_context_popup is not popup:
                    return
                try:
                    left = popup.winfo_rootx()
                    top = popup.winfo_rooty()
                    right = left + popup.winfo_width()
                    bottom = top + popup.winfo_height()
                    if left <= event.x_root <= right and top <= event.y_root <= bottom:
                        return
                except tk.TclError:
                    return
                self.close_active_themed_context_menu()

            try:
                funcid = owner.bind("<ButtonPress>", close_if_clicked_outside, add="+")
                self.active_themed_context_binding = (owner, "<ButtonPress>", funcid)
            except tk.TclError:
                pass

        try:
            popup.after(125, install_outside_click_close)
        except tk.TclError:
            pass

    def ask_themed_text(
        self,
        parent: tk.Widget,
        title: str,
        message: str,
        initialvalue: str = "",
    ) -> str | None:
        if ctk is None:
            return simpledialog.askstring(title, message, initialvalue=initialvalue, parent=parent)

        result: dict[str, str | None] = {"value": None}
        prompt = ctk.CTkToplevel(parent)
        prompt.title(title)
        prompt.configure(fg_color=self.APP_BG)
        prompt.resizable(False, False)
        self.set_window_icon(prompt)
        try:
            prompt.transient(parent.winfo_toplevel())
            prompt.grab_set()
        except tk.TclError:
            pass

        shell = ctk.CTkFrame(
            prompt,
            fg_color=self.CARD_BG,
            corner_radius=12,
            border_width=1,
            border_color=self.BORDER,
        )
        shell.pack(fill=tk.BOTH, expand=True, padx=14, pady=14)
        shell.grid_columnconfigure(0, weight=1)

        ctk.CTkLabel(
            shell,
            text=title,
            font=("Segoe UI", 17, "bold"),
            text_color=self.TEXT,
            anchor="w",
        ).grid(row=0, column=0, sticky="ew", padx=16, pady=(14, 2))
        ctk.CTkLabel(
            shell,
            text=message,
            font=("Segoe UI", 11),
            text_color=self.MUTED,
            anchor="w",
            justify="left",
        ).grid(row=1, column=0, sticky="ew", padx=16, pady=(0, 10))

        text_box = ctk.CTkTextbox(
            shell,
            width=430,
            height=110,
            corner_radius=9,
            border_width=1,
            border_color=self.BORDER,
            fg_color=self.ENTRY_BG,
            text_color=self.TEXT,
            font=("Segoe UI", 12),
        )
        text_box.grid(row=2, column=0, sticky="ew", padx=16, pady=(0, 12))
        text_box.insert("1.0", str(initialvalue).replace("\\n", "\n"))

        button_row = ctk.CTkFrame(shell, fg_color="transparent")
        button_row.grid(row=3, column=0, sticky="e", padx=16, pady=(0, 14))

        def cancel() -> None:
            result["value"] = None
            prompt.destroy()

        def save() -> None:
            result["value"] = text_box.get("1.0", "end-1c").strip()
            prompt.destroy()

        ctk.CTkButton(
            button_row,
            text="Cancel",
            command=cancel,
            width=96,
            height=36,
            corner_radius=8,
            fg_color=self.BUTTON_BG,
            hover_color=self.BUTTON_HOVER,
            border_width=1,
            border_color=self.BORDER,
            text_color=self.BUTTON_TEXT,
            font=("Segoe UI", 11, "bold"),
        ).pack(side=tk.LEFT, padx=(0, 8))
        ctk.CTkButton(
            button_row,
            text="Save Text",
            command=save,
            width=116,
            height=36,
            corner_radius=8,
            fg_color=self.ACCENT,
            hover_color=self.ACCENT_DARK,
            text_color="#ffffff",
            font=("Segoe UI", 11, "bold"),
            **self.ctk_button_icon("check", 15, "#ffffff", "left"),
        ).pack(side=tk.LEFT)

        prompt.update_idletasks()
        owner = parent.winfo_toplevel()
        try:
            x = owner.winfo_rootx() + max(40, (owner.winfo_width() - prompt.winfo_reqwidth()) // 2)
            y = owner.winfo_rooty() + max(40, (owner.winfo_height() - prompt.winfo_reqheight()) // 3)
            prompt.geometry(f"{prompt.winfo_reqwidth()}x{prompt.winfo_reqheight()}+{x}+{y}")
        except tk.TclError:
            pass

        def keep_text_prompt_in_front() -> None:
            try:
                owner.deiconify()
                owner.lift()
            except tk.TclError:
                pass
            try:
                prompt.deiconify()
                prompt.lift(owner)
                prompt.focus_force()
            except tk.TclError:
                pass
            try:
                prompt.attributes("-topmost", True)
                prompt.after(350, lambda: prompt.attributes("-topmost", False))
            except tk.TclError:
                pass
            try:
                text_box.focus_set()
            except tk.TclError:
                pass

        keep_text_prompt_in_front()
        prompt.after(100, keep_text_prompt_in_front)
        prompt.protocol("WM_DELETE_WINDOW", cancel)
        prompt.bind("<Escape>", lambda _event: cancel())
        prompt.wait_window()
        try:
            owner.deiconify()
            owner.lift()
            owner.focus_force()
        except tk.TclError:
            pass
        return result["value"]

    def show_import_duplicate_dialog(
        self,
        groups: list[dict[str, object]],
    ) -> dict[str, object]:
        """Let the operator choose exactly which detected duplicate files to remove."""
        suggested = [
            path
            for group in groups
            for path in group.get("duplicates", [])
            if isinstance(path, Path)
        ]
        if ctk is None:
            preview = "\n".join(path.name for path in suggested[:14])
            if len(suggested) > 14:
                preview += f"\n...and {len(suggested) - 14} more"
            remove = messagebox.askyesno(
                "Duplicate files detected",
                "Duplicate PDF/DXF files were found in the shared import folder.\n\n"
                f"Suggested duplicates:\n{preview}\n\nRemove these suggested copies?",
                parent=self.root,
            )
            return {
                "remove": suggested if remove else [],
                "ignore": [] if remove else [self.import_duplicate_signature(group) for group in groups],
            }

        result: dict[str, object] = {"remove": [], "ignore": []}
        dialog = ctk.CTkToplevel(self.root)
        dialog.title("Duplicate files detected")
        dialog.configure(fg_color=self.APP_BG)
        dialog.geometry("820x640")
        dialog.minsize(680, 480)
        self.set_window_icon(dialog)
        try:
            dialog.transient(self.root)
            dialog.grab_set()
        except tk.TclError:
            pass

        shell = ctk.CTkFrame(
            dialog,
            fg_color=self.CARD_BG,
            corner_radius=16,
            border_width=1,
            border_color=self.BORDER,
        )
        shell.pack(fill=tk.BOTH, expand=True, padx=12, pady=12)
        shell.grid_columnconfigure(0, weight=1)
        shell.grid_rowconfigure(2, weight=1)

        header = ctk.CTkFrame(shell, fg_color="transparent")
        header.grid(row=0, column=0, sticky="ew", padx=20, pady=(18, 4))
        header.grid_columnconfigure(1, weight=1)
        ctk.CTkLabel(
            header,
            text="",
            width=38,
            **self.ctk_button_icon("warning", 25, self.WARNING, "left"),
        ).grid(row=0, column=0, rowspan=2, sticky="n", padx=(0, 10))
        ctk.CTkLabel(
            header,
            text="Duplicate files detected",
            font=("Segoe UI", 20, "bold"),
            text_color=self.TEXT,
            anchor="w",
        ).grid(row=0, column=1, sticky="ew")
        ctk.CTkLabel(
            header,
            text=(
                "Choose the files to remove from the shared import folder. "
                "The obvious copy-suffixed versions are selected by default."
            ),
            font=("Segoe UI", 11),
            text_color=self.MUTED,
            anchor="w",
            justify="left",
            wraplength=690,
        ).grid(row=1, column=1, sticky="ew", pady=(2, 0))

        ctk.CTkLabel(
            shell,
            text=f"{len(groups)} duplicate set(s)   |   {len(suggested)} suggested removal(s)",
            font=("Segoe UI", 11, "bold"),
            text_color=self.ACCENT_DARK,
            anchor="w",
        ).grid(row=1, column=0, sticky="ew", padx=20, pady=(8, 8))

        scroll = ctk.CTkScrollableFrame(
            shell,
            fg_color=self.PANEL_BG,
            corner_radius=10,
            border_width=1,
            border_color=self.BORDER,
        )
        scroll.grid(row=2, column=0, sticky="nsew", padx=20, pady=(0, 14))
        scroll.grid_columnconfigure(0, weight=1)
        scroll.grid_columnconfigure(1, weight=0)

        selections: dict[Path, tk.BooleanVar] = {}
        group_files: list[list[Path]] = []
        row = 0
        for index, group in enumerate(groups, start=1):
            canonical = group.get("canonical")
            duplicates = group.get("duplicates", [])
            files = ([canonical] if isinstance(canonical, Path) else []) + (
                [path for path in duplicates if isinstance(path, Path)]
                if isinstance(duplicates, list)
                else []
            )
            if len(files) < 2:
                continue
            group_files.append(files)
            ctk.CTkLabel(
                scroll,
                text=f"Duplicate set {index}",
                font=("Segoe UI", 12, "bold"),
                text_color=self.TEXT,
                anchor="w",
            ).grid(row=row, column=0, columnspan=2, sticky="ew", padx=12, pady=(12 if row else 8, 4))
            row += 1
            for file_index, path in enumerate(files):
                is_suggested_duplicate = file_index > 0
                variable = tk.BooleanVar(value=is_suggested_duplicate)
                selections[path] = variable
                badge = "Suggested original" if file_index == 0 else "Suggested duplicate"
                ctk.CTkCheckBox(
                    scroll,
                    text=f"{path.name}    ({badge})",
                    variable=variable,
                    onvalue=True,
                    offvalue=False,
                    checkbox_width=20,
                    checkbox_height=20,
                    corner_radius=5,
                    border_width=1,
                    fg_color=self.DANGER,
                    hover_color="#b42318",
                    text_color=self.TEXT,
                    font=("Segoe UI", 11),
                ).grid(row=row, column=0, sticky="w", padx=20, pady=4)
                ctk.CTkButton(
                    scroll,
                    text="Open",
                    command=lambda candidate=path: os.startfile(str(candidate.resolve())),
                    width=76,
                    height=30,
                    corner_radius=7,
                    fg_color=self.BUTTON_BG,
                    hover_color=self.BUTTON_HOVER,
                    border_width=1,
                    border_color=self.BORDER,
                    text_color=self.BUTTON_TEXT,
                    font=("Segoe UI", 10, "bold"),
                    **self.ctk_button_icon("open_folder", 14, self.ACCENT_DARK, "left"),
                ).grid(row=row, column=1, sticky="e", padx=(8, 16), pady=4)
                row += 1

        footer = ctk.CTkFrame(shell, fg_color="transparent")
        footer.grid(row=3, column=0, sticky="ew", padx=20, pady=(0, 18))
        footer.grid_columnconfigure(0, weight=1)

        def keep_all() -> None:
            result["remove"] = []
            result["ignore"] = [self.import_duplicate_signature(group) for group in groups]
            dialog.destroy()

        def remove_selected() -> None:
            selected = [path for path, variable in selections.items() if variable.get()]
            for files in group_files:
                if files and all(path in selected for path in files):
                    messagebox.showwarning(
                        "Keep one file",
                        f"Keep at least one file in this duplicate set:\n\n{files[0].name}",
                        parent=dialog,
                    )
                    return
            result["remove"] = selected
            result["ignore"] = []
            dialog.destroy()

        ctk.CTkButton(
            footer,
            text="Keep All",
            command=keep_all,
            width=112,
            height=38,
            corner_radius=8,
            fg_color=self.BUTTON_BG,
            hover_color=self.BUTTON_HOVER,
            border_width=1,
            border_color=self.BORDER,
            text_color=self.BUTTON_TEXT,
            font=("Segoe UI", 11, "bold"),
        ).grid(row=0, column=1, padx=(0, 8))
        ctk.CTkButton(
            footer,
            text="Remove Selected",
            command=remove_selected,
            width=156,
            height=38,
            corner_radius=8,
            fg_color=self.DANGER,
            hover_color="#b42318",
            text_color="#ffffff",
            font=("Segoe UI", 11, "bold"),
            **self.ctk_button_icon("trash", 16, "#ffffff", "left"),
        ).grid(row=0, column=2)

        dialog.protocol("WM_DELETE_WINDOW", keep_all)
        dialog.bind("<Escape>", lambda _event: keep_all())
        dialog.update_idletasks()
        try:
            x = self.root.winfo_rootx() + max(20, (self.root.winfo_width() - dialog.winfo_width()) // 2)
            y = self.root.winfo_rooty() + max(20, (self.root.winfo_height() - dialog.winfo_height()) // 2)
            dialog.geometry(f"{dialog.winfo_width()}x{dialog.winfo_height()}+{x}+{y}")
        except tk.TclError:
            pass
        dialog.wait_window()
        return result

    @staticmethod
    def suggested_pdf_name(process_order: shower_batch.ProcessOrder) -> str:
        identity = programmer.extract_job_number(process_order.job_name) or process_order.job_name
        identity = re.sub(r'[<>:"/\\|?*]+', " ", identity)
        identity = re.sub(r"\s+", " ", identity).strip(" .-")
        return f"Glass Order {process_order.aw_order} - {identity[:100]}.pdf"

