    def ui_icon(self, name: str, size: int = 18, color: str = "#1f5fa8") -> tk.PhotoImage | None:
        legacy_key = (name, size, color)
        key = (name, size, color, "modern_v2")
        cached = self.ui_icon_cache.get(key)
        if cached is None:
            cached = self.ui_icon_cache.get(legacy_key)
        if cached is not None:
            return cached
        if Image is None or ImageDraw is None or ImageTk is None:
            return None

        scale = 5
        canvas_size = max(1, size * scale)
        image = Image.new("RGBA", (canvas_size, canvas_size), (255, 255, 255, 0))
        draw = ImageDraw.Draw(image)
        stroke = max(2, int(round(size * scale / 12)))
        thin = max(1, int(round(stroke * 0.72)))
        view = 24.0
        unit = canvas_size / view

        def xy(x: float, y: float) -> tuple[int, int]:
            return int(round(x * unit)), int(round(y * unit))

        def box(x1: float, y1: float, x2: float, y2: float) -> tuple[int, int, int, int]:
            return (*xy(x1, y1), *xy(x2, y2))

        def line(points: list[tuple[float, float]], width: int | None = None) -> None:
            draw.line([xy(x, y) for x, y in points], fill=color, width=width or stroke, joint="curve")

        def rect(x1: float, y1: float, x2: float, y2: float, radius: float = 3.0, width: int | None = None, fill: str | None = None) -> None:
            draw.rounded_rectangle(box(x1, y1, x2, y2), radius=int(round(radius * unit)), outline=color, width=width or stroke, fill=fill)

        def circle(cx: float, cy: float, r: float, width: int | None = None, fill: str | None = None) -> None:
            draw.ellipse(box(cx - r, cy - r, cx + r, cy + r), outline=color, width=width or stroke, fill=fill)

        def poly(points: list[tuple[float, float]], fill: str | None = None, outline: str | None = None, width: int | None = None) -> None:
            scaled = [xy(x, y) for x, y in points]
            draw.polygon(scaled, fill=fill, outline=outline)
            if outline and width:
                draw.line(scaled + [scaled[0]], fill=outline, width=width, joint="curve")

        def arc(x1: float, y1: float, x2: float, y2: float, start: float, end: float, width: int | None = None) -> None:
            draw.arc(box(x1, y1, x2, y2), start=start, end=end, fill=color, width=width or stroke)

        def document_icon(label: str | None = None) -> None:
            line([(7, 3), (14, 3), (18, 7), (18, 21), (6, 21), (6, 3), (7, 3)])
            line([(14, 3.2), (14, 7.2), (18, 7.2)], thin)
            if label == "dxf":
                line([(8.6, 14.8), (11.0, 12.0), (13.0, 15.0), (15.5, 11.0)], thin)
                circle(8.6, 14.8, 0.75, fill=color, width=thin)
                circle(15.5, 11.0, 0.75, fill=color, width=thin)
            elif label == "orders":
                line([(9, 10), (15, 10)], thin)
                line([(9, 13), (15, 13)], thin)
                line([(9, 16), (14, 16)], thin)
                circle(7.6, 10, 0.35, fill=color, width=thin)
                circle(7.6, 13, 0.35, fill=color, width=thin)
                circle(7.6, 16, 0.35, fill=color, width=thin)
            else:
                line([(8.7, 11), (15.3, 11)], thin)
                line([(8.7, 14), (15.3, 14)], thin)
                line([(8.7, 17), (13.8, 17)], thin)

        icon = name.lower().replace("-", "_")
        if icon in {"folder", "open_folder"}:
            rect(3, 7.5, 21, 19, radius=2.6)
            line([(4.5, 8), (8.7, 8), (10.1, 10.3), (19.5, 10.3)], thin)
        elif icon in {"network", "network_folder"}:
            rect(3, 6.8, 21, 17.3, radius=2.4, width=thin)
            line([(4.4, 7.2), (8.7, 7.2), (10.1, 9.3), (19.5, 9.3)], thin)
            circle(7.0, 20.0, 1.25, fill=color, width=thin)
            circle(12.0, 20.0, 1.25, fill=color, width=thin)
            circle(17.0, 20.0, 1.25, fill=color, width=thin)
            line([(7.0, 17.5), (7.0, 18.7)], thin)
            line([(12.0, 17.5), (12.0, 18.7)], thin)
            line([(17.0, 17.5), (17.0, 18.7)], thin)
            line([(7.0, 18.3), (17.0, 18.3)], thin)
        elif icon == "archive":
            rect(4.0, 8.0, 20.0, 20.0, radius=2.0, width=thin)
            rect(3.0, 5.0, 21.0, 9.0, radius=1.5, width=thin)
            line([(9.0, 12.0), (15.0, 12.0)], thin)
            line([(12.0, 12.0), (12.0, 17.0)], thin)
            poly([(9.7, 15.3), (12.0, 18.0), (14.3, 15.3)], fill=color)
        elif icon == "restore":
            rect(3.5, 8.0, 20.5, 19.0, radius=2.4, width=thin)
            line([(4.7, 8.4), (9.0, 8.4), (10.3, 10.4), (19.3, 10.4)], thin)
            arc(7.0, 10.0, 17.5, 20.5, 145, 355, width=thin)
            poly([(7.0, 10.4), (7.4, 14.2), (10.3, 12.0)], fill=color)
        elif icon in {"scan", "search"}:
            circle(10.5, 10.5, 5.8)
            line([(15.0, 15.0), (20.0, 20.0)], stroke)
            circle(10.5, 10.5, 2.0, width=thin)
        elif icon in {"check", "check_circle", "ready", "checked"}:
            circle(12, 12, 8.3)
            line([(7.7, 12.2), (10.5, 15.0), (16.7, 8.7)], stroke)
        elif icon == "play":
            circle(12, 12, 8.5, width=thin)
            poly([(10, 8), (16.2, 12), (10, 16)], fill=color)
        elif icon == "eye":
            line([(3.8, 12), (6.8, 8.3), (12, 6.8), (17.2, 8.3), (20.2, 12), (17.2, 15.7), (12, 17.2), (6.8, 15.7), (3.8, 12)], thin)
            circle(12, 12, 2.7, fill=color, width=thin)
        elif icon == "trash":
            line([(5.5, 7), (18.5, 7)], stroke)
            line([(9, 4.7), (15, 4.7)], thin)
            rect(7, 7.5, 17, 20, radius=2.0, width=thin)
            line([(10, 10.2), (10, 17.2)], thin)
            line([(14, 10.2), (14, 17.2)], thin)
        elif icon == "refresh":
            arc(4.7, 5.0, 19.3, 19.6, 35, 305)
            poly([(17.8, 5.3), (20.8, 5.5), (19.2, 8.2)], fill=color)
        elif icon in {"settings", "gear"}:
            circle(12, 12, 4.0, width=stroke)
            circle(12, 12, 1.5, fill=color, width=thin)
            for x1, y1, x2, y2 in (
                (12, 3, 12, 6),
                (12, 18, 12, 21),
                (3, 12, 6, 12),
                (18, 12, 21, 12),
                (5.6, 5.6, 7.7, 7.7),
                (16.3, 16.3, 18.4, 18.4),
                (18.4, 5.6, 16.3, 7.7),
                (7.7, 16.3, 5.6, 18.4),
            ):
                line([(x1, y1), (x2, y2)], thin)
        elif icon == "rotate_left":
            arc(4.5, 4.5, 19.5, 19.5, 250, 360, width=stroke)
            arc(4.5, 4.5, 19.5, 19.5, 0, 205, width=stroke)
            poly([(4.3, 9.1), (5.6, 4.8), (9.2, 7.9)], fill=color)
        elif icon == "rotate_right":
            arc(4.5, 4.5, 19.5, 19.5, 335, 360, width=stroke)
            arc(4.5, 4.5, 19.5, 19.5, 0, 290, width=stroke)
            poly([(19.7, 9.1), (14.8, 7.9), (18.4, 4.8)], fill=color)
        elif icon == "undo":
            arc(5, 6, 20, 20, 210, 30)
            poly([(7.3, 5.0), (3.5, 8.5), (8.5, 9.0)], fill=color)
        elif icon == "redo":
            arc(4, 6, 19, 20, 150, 330)
            poly([(16.7, 5.0), (20.5, 8.5), (15.5, 9.0)], fill=color)
        elif icon == "link":
            rect(3.8, 9.4, 12.6, 15.2, radius=2.8, width=thin)
            rect(11.4, 8.8, 20.2, 14.6, radius=2.8, width=thin)
            line([(9.0, 12.3), (15.0, 11.7)], thin)
        elif icon == "clock":
            circle(12, 12, 8.5)
            line([(12, 7.3), (12, 12.3), (15.7, 14.2)], thin)
        elif icon in {"file", "pdf"}:
            document_icon("pdf")
        elif icon in {"dxf", "program"}:
            document_icon("dxf")
        elif icon == "orders":
            document_icon("orders")
        elif icon == "save":
            rect(4.5, 4.5, 19.5, 19.5, radius=2.5)
            rect(7.4, 5.7, 16.4, 10.0, radius=1.0, width=thin)
            line([(8, 17), (16, 17)], thin)
            line([(16.5, 4.8), (19.1, 7.4)], thin)
        elif icon == "edit":
            line([(6.0, 18.0), (7.2, 13.8), (15.8, 5.2), (18.8, 8.2), (10.2, 16.8), (6.0, 18.0)], thin)
            line([(14.4, 6.6), (17.4, 9.6)], thin)
        elif icon == "indicator":
            circle(12, 12, 4.4, fill=color)
            line([(12, 3.8), (12, 7.0)], thin)
            line([(12, 17.0), (12, 20.2)], thin)
            line([(3.8, 12), (7.0, 12)], thin)
            line([(17.0, 12), (20.2, 12)], thin)
        elif icon == "flip":
            line([(5, 8), (18, 8)], stroke)
            poly([(18, 5.2), (21, 8), (18, 10.8)], fill=color)
            line([(19, 16), (6, 16)], stroke)
            poly([(6, 13.2), (3, 16), (6, 18.8)], fill=color)
        elif icon == "text":
            line([(5, 6), (19, 6)], stroke)
            line([(12, 6), (12, 18)], stroke)
            line([(8.4, 18), (15.6, 18)], stroke)
        elif icon in {"x", "close"}:
            circle(12, 12, 8.5, width=thin)
            line([(8.5, 8.5), (15.5, 15.5)], stroke)
            line([(15.5, 8.5), (8.5, 15.5)], stroke)
        elif icon == "chevron_left":
            line([(14.7, 6.2), (8.7, 12), (14.7, 17.8)], stroke)
        elif icon == "chevron_right":
            line([(9.3, 6.2), (15.3, 12), (9.3, 17.8)], stroke)
        elif icon == "chevron_up":
            line([(6.2, 14.7), (12, 8.7), (17.8, 14.7)], stroke)
        elif icon == "chevron_down":
            line([(6.2, 9.3), (12, 15.3), (17.8, 9.3)], stroke)
        elif icon in {"send", "paper_plane"}:
            poly([(3.8, 5.2), (21, 3.2), (14.9, 20.8), (11.5, 13.3)], outline=color, width=thin)
            line([(11.5, 13.3), (21, 3.2)], thin)
        elif icon == "image":
            rect(4, 5, 20, 19, radius=2.2)
            circle(8, 9, 1.3, fill=color, width=thin)
            line([(5.8, 17), (10, 12.7), (12.4, 15.0), (15.8, 11.2), (19, 17)], thin)
        elif icon == "info":
            circle(12, 12, 8.5)
            circle(12, 8.1, 0.9, fill=color, width=thin)
            line([(12, 11), (12, 16.4)], stroke)
        elif icon == "help":
            circle(12, 12, 8.5)
            arc(8.5, 6.8, 15.5, 13.2, 205, 330, width=stroke)
            line([(12, 12.8), (12, 15.0)], stroke)
            circle(12, 17.4, 0.9, fill=color, width=thin)
        elif icon == "warning":
            poly([(12, 3.7), (21, 20), (3, 20)], outline=color, width=stroke)
            line([(12, 9), (12, 14.4)], stroke)
            circle(12, 17.0, 0.85, fill=color, width=thin)
        elif icon == "bug":
            circle(12, 12.5, 5.0, width=stroke)
            line([(12, 7.5), (12, 18.2)], thin)
            line([(7.2, 10.0), (4.2, 8.2)], thin)
            line([(16.8, 10.0), (19.8, 8.2)], thin)
            line([(7.0, 13.0), (3.8, 13.0)], thin)
            line([(17.0, 13.0), (20.2, 13.0)], thin)
            line([(7.4, 16.0), (4.7, 18.2)], thin)
            line([(16.6, 16.0), (19.3, 18.2)], thin)
            arc(8.5, 3.8, 15.5, 10.0, 190, 350, width=thin)
        elif icon == "minus_circle":
            circle(12, 12, 8.5)
            line([(8, 12), (16, 12)], stroke)
        elif icon == "plus":
            circle(12, 12, 8.5, width=thin)
            line([(12, 7.5), (12, 16.5)], stroke)
            line([(7.5, 12), (16.5, 12)], stroke)
        else:
            document_icon(None)

        resampling = getattr(getattr(Image, "Resampling", Image), "LANCZOS")
        image = image.resize((size, size), resampling)
        self.ui_icon_pil_cache[key] = image.copy()
        self.ui_icon_pil_cache[legacy_key] = image.copy()
        photo = ImageTk.PhotoImage(image)
        self.ui_icon_cache[key] = photo
        self.ui_icon_cache[legacy_key] = photo
        return photo

    def ctk_button_icon(self, name: str, size: int = 16, color: str = "#1f5fa8", compound: str = "left") -> dict[str, object]:
        if ctk is None:
            return {}
        key = (name, size, color)
        cached = self.ctk_icon_cache.get(key)
        if cached is None:
            self.ui_icon(name, size=size, color=color)
            image = self.ui_icon_pil_cache.get(key)
            if image is None:
                return {}
            cached = ctk.CTkImage(light_image=image, dark_image=image, size=(size, size))
            self.ctk_icon_cache[key] = cached
        return {"image": cached, "compound": compound}

    def button_icon(self, name: str, size: int = 16, color: str = "#1f5fa8", compound: str = tk.LEFT) -> dict[str, object]:
        icon = self.ui_icon(name, size=size, color=color)
        if icon is None:
            return {}
        return {"image": icon, "compound": compound}

    def app_logo_image(self, size: int = 24) -> Any:
        if ctk is None or Image is None:
            return self.ctk_button_icon("dxf", size, self.ACCENT_DARK).get("image")
        if bool(getattr(self, "dark_mode_var", tk.BooleanVar(value=False)).get()):
            return self.ctk_button_icon("dxf", size, self.ACCENT_DARK).get("image")
        key = ("app_logo", size, "native")
        cached = self.ctk_icon_cache.get(key)
        if cached is not None:
            return cached
        image = None
        if self.APP_ICON_PNG_PATH.exists():
            try:
                image = Image.open(self.APP_ICON_PNG_PATH).convert("RGBA")
                resampling = getattr(getattr(Image, "Resampling", Image), "LANCZOS")
                image.thumbnail((size, size), resampling)
                canvas = Image.new("RGBA", (size, size), (255, 255, 255, 0))
                canvas.paste(image, ((size - image.width) // 2, (size - image.height) // 2), image)
                image = canvas
            except Exception:
                image = None
        if image is None:
            self.ui_icon("dxf", size=size, color=self.ACCENT_DARK)
            image = self.ui_icon_pil_cache.get(("dxf", size, self.ACCENT_DARK))
        if image is None:
            return None
        cached = ctk.CTkImage(light_image=image, dark_image=image, size=(size, size))
        self.ctk_icon_cache[key] = cached
        return cached

    def make_app_header(self, parent: Any, title: str, padx: int = 0) -> Any:
        header = ctk.CTkFrame(parent, fg_color="transparent")
        header.pack(fill=tk.X, padx=padx, pady=(0, 12))

        row = ctk.CTkFrame(header, fg_color="transparent", height=48)
        row.pack(fill=tk.X)
        row.pack_propagate(False)

        icon_box = ctk.CTkFrame(
            row,
            fg_color=self.SOFT_CARD_BG if not self.dark_mode_var.get() else self.PANEL_BG,
            corner_radius=12,
            border_width=1,
            border_color=self.BORDER,
            width=42,
            height=42,
        )
        icon_box.pack(side=tk.LEFT, pady=3)
        icon_box.pack_propagate(False)
        logo = self.app_logo_image(30)
        ctk.CTkLabel(icon_box, text="", image=logo, width=34, height=34).pack(expand=True)

        title_stack = ctk.CTkFrame(row, fg_color="transparent")
        title_stack.pack(side=tk.LEFT, fill=tk.Y, expand=True, padx=(12, 0))
        ctk.CTkLabel(
            title_stack,
            text=title,
            font=("Segoe UI", 22, "bold"),
            text_color=self.TEXT,
            anchor="w",
        ).pack(anchor=tk.W)
        ctk.CTkLabel(
            title_stack,
            text="Production-ready shower sketch and DXF workflow",
            font=("Segoe UI", 11),
            text_color=self.MUTED,
            anchor="w",
        ).pack(anchor=tk.W, pady=(0, 2))
        return header
    def icon_label(self, parent: ttk.Frame, icon_name: str, size: int = 18, color: str = "#1f5fa8", style: str = "Card.TLabel") -> None:
        icon = self.ui_icon(icon_name, size=size, color=color)
        if icon is not None:
            ttk.Label(parent, image=icon, style=style).pack(side=tk.LEFT, padx=(0, 8))

    def build_ui(self) -> None:
        if ctk is None:
            raise RuntimeError("CustomTkinter is required for the modern Shower Programmer GUI.")

        outer = ctk.CTkFrame(self.root, fg_color=self.APP_BG, corner_radius=0)
        outer.pack(fill=tk.BOTH, expand=True, padx=14, pady=14)
        outer.grid_columnconfigure(0, weight=0)
        outer.grid_columnconfigure(1, weight=1)
        outer.grid_rowconfigure(0, weight=1)

        sidebar = ctk.CTkFrame(
            outer,
            fg_color=self.SIDEBAR_BG,
            corner_radius=18,
            border_width=1,
            border_color=self.SIDEBAR_BORDER,
            width=268,
        )
        sidebar.grid(row=0, column=0, sticky="ns", padx=(0, 14))
        sidebar.grid_propagate(False)
        sidebar.grid_columnconfigure(0, weight=1)
        # Keep the send controls permanently visible at the bottom. The middle
        # workflow/tools region uses a fixed frame so the sidebar has no internal
        # scrollbar and all controls remain part of one stable panel.
        sidebar.grid_rowconfigure(1, weight=1, minsize=0)

        brand = ctk.CTkFrame(sidebar, fg_color="transparent")
        brand.grid(row=0, column=0, sticky="ew", padx=16, pady=(14, 10))
        brand.grid_columnconfigure(1, weight=1)

        logo_box = ctk.CTkFrame(
            brand,
            fg_color="#eaf2ff" if not self.dark_mode_var.get() else self.SIDEBAR_CARD_BG,
            corner_radius=12,
            width=44,
            height=44,
        )
        logo_box.grid(row=0, column=0, rowspan=2, sticky="w")
        logo_box.grid_propagate(False)
        ctk.CTkLabel(logo_box, text="", image=self.app_logo_image(32)).pack(expand=True)
        ctk.CTkLabel(
            brand,
            text="Shower Programmer",
            font=("Segoe UI", 16, "bold"),
            text_color=self.SIDEBAR_TEXT,
            anchor="w",
        ).grid(row=0, column=1, sticky="ew", padx=(12, 0))
        ctk.CTkLabel(
            brand,
            text="CNC batch control",
            font=("Segoe UI", 11),
            text_color=self.SIDEBAR_MUTED,
            anchor="w",
        ).grid(row=1, column=1, sticky="ew", padx=(12, 0))

        center_stack = ctk.CTkFrame(
            sidebar,
            fg_color="transparent",
            corner_radius=0,
            border_width=0,
        )
        center_stack.grid(row=1, column=0, sticky="nsew", padx=(0, 3), pady=(0, 0))
        center_stack.grid_columnconfigure(0, weight=1)

        ctk.CTkLabel(
            center_stack,
            text="WORKFLOW",
            font=("Segoe UI", 10, "bold"),
            text_color=self.SIDEBAR_MUTED,
            anchor="center",
        ).pack(fill=tk.X, padx=18, pady=(0, 5))

        workflow = ctk.CTkFrame(center_stack, fg_color="transparent")
        workflow.pack(fill=tk.X, padx=12)
        scan_button = self.make_sidebar_button(workflow, "Scan Orders", "scan", self.scan_orders, primary=True)
        process_selected_button = self.make_sidebar_button(workflow, "Process Selected", "check_circle", self.process_selected)
        process_all_button = self.make_sidebar_button(workflow, "Process All", "play", self.process_all_orders)
        review_order_button = self.make_sidebar_button(workflow, "Review Order", "eye", self.open_order_review)
        self.checked_action_button = self.make_sidebar_button(
            workflow,
            "Mark Checked",
            "check",
            self.toggle_selected_orders_checked,
        )
        workflow_buttons = [
            scan_button,
            process_selected_button,
            process_all_button,
            review_order_button,
            self.checked_action_button,
        ]
        for index, button in enumerate(workflow_buttons):
            button.pack(fill=tk.X, pady=(0, 0 if index == len(workflow_buttons) - 1 else 6))

        options_card = ctk.CTkFrame(
            center_stack,
            fg_color=self.SIDEBAR_CARD_BG,
            corner_radius=14,
            border_width=1,
            border_color=self.SIDEBAR_BORDER,
        )
        options_card.pack(fill=tk.X, padx=12, pady=(8, 0))
        ctk.CTkLabel(
            options_card,
            text="Run Options",
            font=("Segoe UI", 12, "bold"),
            text_color=self.SIDEBAR_TEXT,
            anchor="w",
        ).pack(fill=tk.X, padx=14, pady=(9, 6))
        self.make_option_switch(options_card, "Skip Sketch output", self.skip_pdf_var).pack(fill=tk.X, padx=14, pady=(0, 6))
        self.make_option_switch(options_card, "Skip DXF output", self.skip_dxf_var).pack(fill=tk.X, padx=14, pady=(0, 6))
        self.make_option_switch(options_card, "REMAKE batch", self.remake_var).pack(fill=tk.X, padx=14, pady=(0, 10))

        ctk.CTkLabel(
            center_stack,
            text="TOOLS",
            font=("Segoe UI", 10, "bold"),
            text_color=self.SIDEBAR_MUTED,
            anchor="center",
        ).pack(fill=tk.X, padx=18, pady=(12, 7))

        tools = ctk.CTkFrame(center_stack, fg_color="transparent")
        tools.pack(fill=tk.X, padx=12)
        tool_buttons = [
            self.make_sidebar_button(tools, "Clear Sketch Memory", "trash", self.clear_sketch_memory, compact=True),
            self.make_sidebar_button(tools, "Clear Program Memory", "program", self.clear_program_memory, compact=True),
            self.make_sidebar_button(tools, "Validate Selected", "check_circle", self.validate_selected_orders, compact=True),
            self.make_sidebar_button(tools, "Settings", "settings", self.open_settings, compact=True),
        ]
        for index, button in enumerate(tool_buttons):
            button.pack(fill=tk.X, pady=(0, 0 if index == len(tool_buttons) - 1 else 6))

        send_card = ctk.CTkFrame(
            sidebar,
            fg_color="#0b5ed7",
            corner_radius=14,
            border_width=1,
            border_color="#2e90fa",
        )
        send_card.grid(row=2, column=0, sticky="ew", padx=12, pady=(10, 14))
        ctk.CTkButton(
            send_card,
            text="Select All Orders",
            command=lambda: self.select_all_orders(),
            height=36,
            corner_radius=10,
            fg_color="transparent",
            hover_color="#1d4ed8",
            border_width=1,
            border_color="#93c5fd",
            text_color="#ffffff",
            font=("Segoe UI", 12, "bold"),
            anchor="w",
            **self.ctk_button_icon("check_circle", 16, "#ffffff", "left"),
        ).pack(fill=tk.X, padx=14, pady=(14, 8))
        ctk.CTkButton(
            send_card,
            text="Review / Send",
            command=self.send_all_to_shop,
            height=42,
            corner_radius=10,
            fg_color="#ffffff" if not self.dark_mode_var.get() else self.ACCENT,
            hover_color="#eaf2ff" if not self.dark_mode_var.get() else self.ACCENT_DARK,
            text_color="#1849a9" if not self.dark_mode_var.get() else "#ffffff",
            font=("Segoe UI", 13, "bold"),
            anchor="w",
            **self.ctk_button_icon("send", 17, "#1849a9" if not self.dark_mode_var.get() else "#ffffff", "left"),
        ).pack(fill=tk.X, padx=14, pady=(0, 14))

        sidebar_layout: dict[str, bool] = {"compact": False}

        def arrange_sidebar(event: tk.Event | None = None) -> None:
            compact = int(getattr(event, "height", sidebar.winfo_height())) < 950
            if sidebar_layout["compact"] == compact and event is not None:
                return
            sidebar_layout["compact"] = compact
            for index, button in enumerate(workflow_buttons):
                button.configure(height=36 if compact else 44)
                button.pack_configure(pady=(0, 0 if index == len(workflow_buttons) - 1 else (3 if compact else 6)))
            for index, button in enumerate(tool_buttons):
                button.configure(height=32 if compact else 38)
                button.pack_configure(pady=(0, 0 if index == len(tool_buttons) - 1 else (3 if compact else 6)))

        sidebar.bind("<Configure>", arrange_sidebar, add="+")

        content = ctk.CTkFrame(outer, fg_color="transparent")
        content.grid(row=0, column=1, sticky="nsew")
        content.grid_columnconfigure(0, weight=1)
        content.grid_rowconfigure(2, weight=1)

        top_bar = ctk.CTkFrame(content, fg_color="transparent")
        top_bar.grid(row=0, column=0, sticky="ew", pady=(0, 12))
        top_bar.grid_columnconfigure(0, weight=1)

        title_stack = ctk.CTkFrame(top_bar, fg_color="transparent")
        title_stack.grid(row=0, column=0, sticky="ew")
        title_row = ctk.CTkFrame(title_stack, fg_color="transparent")
        title_row.pack(anchor=tk.W, fill=tk.X)
        ctk.CTkLabel(
            title_row,
            text="Production Dashboard",
            font=("Segoe UI", 27, "bold"),
            text_color=self.TEXT,
            anchor="w",
        ).pack(side=tk.LEFT)
        version_badge = ctk.CTkButton(
            title_row,
            text=self.APP_VERSION,
            command=self.open_changelog,
            width=58,
            height=26,
            corner_radius=13,
            fg_color=self.ACCENT_LIGHT,
            hover_color=self.BUTTON_HOVER,
            border_width=1,
            border_color=self.ACCENT,
            text_color=self.ACCENT_DARK,
            font=("Segoe UI", 10, "bold"),
        )
        version_badge.pack(side=tk.LEFT, padx=(10, 0), pady=(3, 0))
        self.attach_tooltip(version_badge, f"View the {self.APP_VERSION} changelog")
        ctk.CTkLabel(
            title_stack,
            text="Import orders, process CNC files, review output, and send to the shop from one screen.",
            font=("Segoe UI", 12),
            text_color=self.MUTED,
            anchor="w",
        ).pack(anchor=tk.W, pady=(1, 0))

        header_actions = ctk.CTkFrame(
            top_bar,
            fg_color=self.CARD_BG,
            corner_radius=14,
            border_width=1,
            border_color=self.BORDER,
        )
        header_actions.grid(row=0, column=1, sticky="e")
        header_action_inner = ctk.CTkFrame(header_actions, fg_color="transparent")
        header_action_inner.pack(padx=9, pady=8)
        ctk.CTkSwitch(
            header_action_inner,
            text="Dark mode",
            variable=self.dark_mode_var,
            command=self.toggle_color_mode,
            progress_color=self.ACCENT,
            button_color="#ffffff",
            button_hover_color="#f2f4f7",
            fg_color="#98a2b3" if not self.dark_mode_var.get() else "#475467",
            text_color=self.TEXT,
            font=("Segoe UI", 10, "bold"),
        ).pack(side=tk.LEFT, padx=(0, 10))
        self.make_tool_button(
            header_action_inner,
            "Local Input",
            "folder",
            self.open_input_folder,
            width=118,
        ).pack(side=tk.LEFT, padx=(0, 7))
        network_input_button = self.make_tool_button(
            header_action_inner,
            "Network Input",
            "network_folder",
            self.open_network_input_folder,
            width=132,
        )
        network_input_button.pack(side=tk.LEFT, padx=(0, 7))
        self.attach_tooltip(network_input_button, "Open the shared Showers Programmer Input folder")
        self.make_tool_button(header_action_inner, "Latest Batch", "clock", self.open_latest_batch, width=126).pack(side=tk.LEFT)

        self.test_mode_banner = ctk.CTkFrame(
            content,
            fg_color="#b54708",
            corner_radius=12,
            border_width=1,
            border_color="#fdb022",
        )
        self.test_mode_banner.grid(row=1, column=0, sticky="ew", pady=(0, 12))
        self.test_mode_banner.grid_columnconfigure(1, weight=1)
        ctk.CTkLabel(
            self.test_mode_banner,
            text="TEST MODE",
            text_color="#ffffff",
            font=("Segoe UI", 14, "bold"),
        ).grid(row=0, column=0, padx=(14, 12), pady=10, sticky="w")
        ctk.CTkLabel(
            self.test_mode_banner,
            textvariable=self.test_mode_banner_var,
            text_color="#ffffff",
            font=("Segoe UI", 12, "bold"),
            anchor="w",
        ).grid(row=0, column=1, padx=(0, 12), pady=10, sticky="ew")
        ctk.CTkButton(
            self.test_mode_banner,
            text="Exit Test Mode",
            command=self.exit_test_mode,
            width=126,
            height=32,
            corner_radius=9,
            fg_color="#ffffff",
            hover_color="#fff7ed",
            text_color="#9a3412",
            font=("Segoe UI", 11, "bold"),
        ).grid(row=0, column=2, padx=(0, 12), pady=7, sticky="e")
        self.test_mode_banner.grid_remove()

        table_outer = self.make_section(content, "Orders", "orders")
        table_outer.grid(row=2, column=0, sticky="nsew")
        table_outer.grid_columnconfigure(0, weight=1)
        table_outer.grid_rowconfigure(1, weight=1)

        table_frame = ctk.CTkFrame(table_outer, fg_color="transparent")
        table_frame.grid(row=1, column=0, sticky="nsew", padx=12, pady=(0, 12))
        table_frame.columnconfigure(0, weight=1)
        table_frame.rowconfigure(1, weight=1)

        table_toolbar = ctk.CTkFrame(table_frame, fg_color="transparent")
        table_toolbar.grid(row=0, column=0, columnspan=2, sticky="ew", pady=(0, 6))
        table_toolbar.grid_columnconfigure(1, weight=1)

        search_controls = ctk.CTkFrame(table_toolbar, fg_color="transparent")
        search_controls.grid(row=0, column=0, sticky="w")

        order_search = ctk.CTkEntry(
            search_controls,
            textvariable=self.order_search_var,
            width=220,
            height=32,
            corner_radius=9,
            border_width=1,
            border_color=self.BORDER,
            fg_color=self.ENTRY_BG,
            text_color=self.TEXT,
            placeholder_text="Search order number",
            font=("Segoe UI", 11),
        )
        order_search.pack(side=tk.LEFT)
        order_search.bind("<Return>", lambda _event: self.find_order_from_search())
        find_order_button = ctk.CTkButton(
            search_controls,
            text="Find",
            command=self.find_order_from_search,
            width=76,
            height=32,
            corner_radius=9,
            fg_color=self.ACCENT_LIGHT,
            hover_color=self.BUTTON_HOVER,
            border_width=1,
            border_color=self.ACCENT,
            text_color=self.ACCENT_DARK,
            font=("Segoe UI", 11, "bold"),
            **self.ctk_button_icon("search", 14, self.ACCENT_DARK, "left"),
        )
        find_order_button.pack(side=tk.LEFT, padx=(8, 0))
        self.attach_tooltip(find_order_button, "Find and highlight an order in the current table")

        orders_metrics = ctk.CTkFrame(table_toolbar, fg_color="transparent")
        orders_metrics.grid(row=0, column=1)
        self.add_compact_metric_badge(orders_metrics, "orders", "Orders", "orders", self.ACCENT_DARK, 112)
        self.add_compact_metric_badge(orders_metrics, "ready", "Ready", "check_circle", self.SUCCESS, 106)
        self.add_compact_metric_badge(orders_metrics, "issues", "Issues", "warning", self.WARNING, 106)
        self.add_compact_metric_badge(orders_metrics, "processed", "Processed", "refresh", "#7c3aed", 132)
        self.add_compact_metric_badge(orders_metrics, "checked", "Checked", "checked", self.ACCENT_DARK, 116)

        resize_hint = ctk.CTkLabel(
            table_toolbar,
            text="Drag the ⋮ grips on either side of a header to resize that column",
            text_color=self.MUTED,
            font=("Segoe UI", 10, "italic"),
            anchor="e",
        )
        resize_hint.grid(row=0, column=2, sticky="e")

        toolbar_layout: dict[str, bool] = {"compact": False}

        def arrange_orders_toolbar(event: tk.Event | None = None) -> None:
            compact = int(getattr(event, "width", table_toolbar.winfo_width())) < 1380
            if toolbar_layout["compact"] == compact and event is not None:
                return
            toolbar_layout["compact"] = compact
            search_controls.grid_forget()
            orders_metrics.grid_forget()
            resize_hint.grid_forget()
            if compact:
                orders_metrics.grid(row=0, column=0, columnspan=3, pady=(0, 6))
                search_controls.grid(row=1, column=0, sticky="w")
                resize_hint.grid(row=1, column=2, sticky="e")
            else:
                search_controls.grid(row=0, column=0, sticky="w")
                orders_metrics.grid(row=0, column=1)
                resize_hint.grid(row=0, column=2, sticky="e")

        table_toolbar.bind("<Configure>", arrange_orders_toolbar, add="+")

        columns = self.ORDER_TREE_COLUMNS
        self.tree = ttk.Treeview(
            table_frame,
            columns=columns,
            displaycolumns=self.ORDER_TREE_DISPLAY_COLUMNS,
            show="tree headings",
            selectmode="extended",
            style="Orders.Treeview",
        )
        headings = {
            "status": "Status",
            "processed": "Processed",
            "delivery": "Delivery",
            "order": "A&W",  # Hidden internal lookup column.
            "sent": "Sent",
            "job": "Job",
            "customer": "Customer",
            "items": "Items",
            "review": "Mark Checked",
            "issues": "Issues",
        }
        self.order_tree_heading_labels = {"#0": "Batch / Process List", **headings}
        widths = {
            "status": 88,
            "processed": 190,
            "delivery": 102,
            "order": 88,
            "sent": 112,
            "job": 250,
            "customer": 205,
            "items": 110,
            "review": 134,
            "issues": 620,
        }
        self.tree.heading(
            "#0",
            text=self.order_tree_heading_text("Batch / Process List"),
            anchor=tk.CENTER,
            command=lambda: self.sort_orders_by_column("#0"),
        )
        self.tree.column("#0", width=270, minwidth=210, anchor=tk.W, stretch=True)
        for col in columns:
            self.tree.heading(
                col,
                text=self.order_tree_heading_text(headings[col]),
                anchor=tk.CENTER,
                command=lambda column=col: self.sort_orders_by_column(column),
            )
            min_width = {"status": 62, "processed": 150, "issues": 260}.get(col, 74)
            stretch = col in {"job", "customer", "issues"}
            self.tree.column(col, width=widths[col], minwidth=min_width, anchor=tk.W, stretch=stretch)

        self.tree.tag_configure("BATCH", foreground=self.ACCENT_DARK, background=self.SOFT_CARD_BG, font=("Segoe UI", 10, "bold"))
        self.tree.tag_configure("OK", foreground=self.SUCCESS)
        self.tree.tag_configure("READY", foreground=self.ACCENT_DARK)
        self.tree.tag_configure("ISSUES", foreground=self.WARNING)
        self.tree.tag_configure("FAILED", foreground=self.DANGER)
        self.tree.tag_configure("SKIPPED", foreground=self.DANGER)
        self.tree.tag_configure("SENT", background=self.TREE_SENT_BG)
        self.tree.tag_configure(
            "CHECKED",
            foreground=self.TREE_CHECKED_TEXT,
            background=self.TREE_CHECKED_BG,
            font=("Segoe UI", 10, "bold"),
        )
        self.tree.tag_configure(
            "SENT_CHECKED",
            foreground=self.TREE_CHECKED_TEXT,
            background=self.TREE_SENT_CHECKED_BG,
            font=("Segoe UI", 10, "bold"),
        )
        self.tree.bind("<Double-1>", self.open_order_review)
        self.tree.bind("<Button-3>", self.open_orders_context_menu)
        self.tree.bind("<<TreeviewSelect>>", self.on_orders_tree_selection, add="+")
        self.tree.bind("<Control-a>", self.select_all_orders)
        self.tree.bind("<Control-A>", self.select_all_orders)
        self.tree.bind("<Motion>", self.update_orders_tree_resize_cursor, add="+")
        self.tree.bind("<Leave>", self.clear_orders_tree_resize_cursor, add="+")

        y_scroll = ttk.Scrollbar(table_frame, orient=tk.VERTICAL, command=self.tree.yview)
        x_scroll = ttk.Scrollbar(table_frame, orient=tk.HORIZONTAL, command=self.tree.xview)
        self.tree.configure(yscrollcommand=y_scroll.set, xscrollcommand=x_scroll.set)
        self.tree.grid(row=1, column=0, sticky="nsew")
        y_scroll.grid(row=1, column=1, sticky="ns")
        x_scroll.grid(row=2, column=0, sticky="ew")

        bottom = ctk.CTkFrame(
            content,
            fg_color=self.CARD_BG,
            corner_radius=14,
            border_width=1,
            border_color=self.BORDER,
        )
        bottom.grid(row=3, column=0, sticky="ew", pady=(12, 0))
        bottom.columnconfigure(0, weight=1)
        bottom.columnconfigure(1, weight=0)
        bottom.columnconfigure(2, weight=0)
        self.progress = ModernProgressBar(bottom, self, height=14)
        self.progress.grid(row=0, column=0, columnspan=2, sticky="ew", padx=14, pady=(12, 0), ipady=2)
        self.status_label = ctk.CTkLabel(
            bottom,
            textvariable=self.status_var,
            anchor="w",
            text_color=self.MUTED,
            font=("Segoe UI", 12),
            width=520,
        )
        self.status_label.grid(row=1, column=0, sticky="ew", padx=14, pady=(9, 2))
        self.activity_detail_label = ctk.CTkLabel(
            bottom,
            textvariable=self.activity_detail_var,
            anchor="w",
            text_color=self.MUTED,
            font=("Segoe UI", 10),
            width=520,
        )
        self.activity_detail_label.grid(row=2, column=0, sticky="ew", padx=14, pady=(0, 10))
        self.network_health_button = self.make_tool_button(
            bottom,
            "Network: Checking",
            "refresh",
            self.open_network_health_dialog,
            width=164,
        )
        self.network_health_button.grid(row=1, column=1, rowspan=2, sticky="e", padx=(8, 0), pady=(9, 10))
        self.cancel_task_button = self.make_tool_button(
            bottom,
            "Cancel",
            "minus_circle",
            self.cancel_background_task,
            width=104,
        )
        self.cancel_task_button.grid(row=1, column=2, rowspan=2, sticky="e", padx=(8, 0), pady=(9, 10))
        self.cancel_task_button.grid_remove()
        self.exit_test_mode_button = self.make_tool_button(
            bottom,
            "Exit Test Mode",
            "restore",
            self.exit_test_mode,
            width=128,
        )
        self.exit_test_mode_button.grid(row=1, column=3, rowspan=2, sticky="e", padx=(8, 0), pady=(9, 10))
        self.exit_test_mode_button.grid_remove()
